          </div>
        </div>
        {!mini && (
          <span style={{ fontSize: 11 * s, fontWeight: 600, color: accent, background: lighten(accent, 0.84), padding: `${3 * s}px ${8 * s}px`, borderRadius: 99, fontVariantNumeric: 'tabular-nums', flexShrink: 0 }}>{events.length}</span>
        )}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {events.map((ev, i) => (
          <div key={i} style={{ display: 'flex', alignItems: 'stretch', gap: 11 * s, padding: `${8.5 * s}px 0`, borderTop: i === 0 ? 'none' : '1px solid var(--w-line)' }}>
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', width: 34 * s, flexShrink: 0 }}>
              <div style={{ fontSize: 9.5 * s, fontWeight: 700, color: 'var(--w-mut)', textTransform: 'uppercase', letterSpacing: '0.04em' }}>{ev.day}</div>
              <div style={{ fontSize: 17 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>{ev.date}</div>
            </div>
            <div style={{ width: 3 * s, borderRadius: 99, background: ev.tone, flexShrink: 0 }} />
            <div style={{ minWidth: 0, flex: 1, display: 'flex', flexDirection: 'column', gap: 2.5 * s, justifyContent: 'center' }}>
              <div style={{ fontSize: 13 * s, fontWeight: 600, letterSpacing: '-0.01em', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{ev.title}</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 7 * s, fontSize: 11 * s, color: 'var(--w-mut)', fontWeight: 500 }}>
                <span style={{ fontVariantNumeric: 'tabular-nums', fontWeight: 600, color: ev.allDay ? ev.tone : 'var(--w-mut)' }}>{ev.allDay ? 'All day' : ev.time}{!ev.allDay && ev.end ? <span style={{ color: 'var(--w-mut)', fontWeight: 500 }}>–{ev.end}</span> : null}</span>
                {!mini && (
                  <span style={{ display: 'flex', alignItems: 'center', gap: 4 * s, paddingLeft: 7 * s, borderLeft: '1px solid var(--w-line)' }}>
                    <span style={{ width: 6 * s, height: 6 * s, borderRadius: 99, background: ev.tone, flexShrink: 0 }} />
                    {ev.cal}
                  </span>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function BreathingCircleW({ config: c, accent, s, fontStack, mini }) {
  const pattern = c.pattern || 'box';
  const showLabel = c.showLabel !== false;

  const phases = useMemo(() => {
    const n = v => Math.max(0, Number(v) || 0);
    let inh, h1, exh, h2;
    if (pattern === '478') { inh = 4; h1 = 7; exh = 8; h2 = 0; }
    else if (pattern === 'custom') {
      inh = n(c.inhale != null ? c.inhale : 4);
      h1 = n(c.hold != null ? c.hold : 4);
      exh = n(c.exhale != null ? c.exhale : 4);
      h2 = n(c.hold2 != null ? c.hold2 : 0);
    } else { inh = n(c.inhale != null ? c.inhale : 4); h1 = n(c.hold != null ? c.hold : 4); exh = n(c.exhale != null ? c.exhale : 4); h2 = 4; }
    const seq = [];
    if (inh > 0) seq.push({ key: 'inhale', label: 'Breathe in', dur: inh, from: 0, to: 1 });
    if (h1 > 0) seq.push({ key: 'hold', label: 'Hold', dur: h1, from: 1, to: 1 });
    if (exh > 0) seq.push({ key: 'exhale', label: 'Breathe out', dur: exh, from: 1, to: 0 });
    if (h2 > 0) seq.push({ key: 'hold2', label: 'Hold', dur: h2, from: 0, to: 0 });
    if (!seq.length) seq.push({ key: 'inhale', label: 'Breathe in', dur: 4, from: 0, to: 1 });
    const total = seq.reduce((a, p) => a + p.dur, 0);
    return { seq, total };
  }, [pattern, c.inhale, c.hold, c.exhale, c.hold2]);

  const [running, setRunning] = useState(!mini);
  const [started, setStarted] = useState(0);
  const [pausedAt, setPausedAt] = useState(0);
  const now = useNow(running, 60);

  // elapsed seconds within the loop
  const t = useMemo(() => {
    if (!running) return pausedAt;
    return pausedAt + (now.getTime() - started) / 1000;
  }, [running, now, started, pausedAt]);

  const cur = useMemo(() => {
    const { seq, total } = phases;
    let x = t % total;
    for (let i = 0; i < seq.length; i++) {
      const p = seq[i];
      if (x < p.dur || i === seq.length - 1) {
        const localT = Math.min(p.dur, Math.max(0, x));
        const prog = p.dur > 0 ? localT / p.dur : 1;
        // ease for inhale/exhale, flat for holds
        let scale = p.from;
        if (p.from !== p.to) {
          const e = prog < 0.5 ? 2 * prog * prog : 1 - Math.pow(-2 * prog + 2, 2) / 2;
          scale = p.from + (p.to - p.from) * e;
        }
        const remain = Math.ceil(p.dur - localT - 1e-6);
        return { phase: p, scale, remain: Math.max(0, remain) };
      }
      x -= p.dur;
    }
    return { phase: seq[0], scale: 0, remain: 0 };
  }, [t, phases]);

  const start = () => { setStarted(Date.now()); setRunning(true); };
  const pause = () => { setPausedAt(t); setRunning(false); };
  const reset = () => { setPausedAt(0); setStarted(Date.now()); setRunning(false); };

  const box = 150 * s;
  const minScale = 0.42;
  const sc = minScale + (1 - minScale) * cur.scale;
  const fg = accent;

  // ring geometry
  const R = 58, CC = 2 * Math.PI * R;
  const ringOffset = CC * (1 - cur.scale);

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 16 * s, padding: 18 * s, fontFamily: fontStack }}>
      <div style={{ position: 'relative', width: box, height: box, display: 'grid', placeItems: 'center' }}>
        {/* soft outer glow disc */}
        <div style={{
          position: 'absolute', width: box, height: box, borderRadius: '50%',
          background: `radial-gradient(circle, ${lighten(fg, 0.32)}33 0%, transparent 68%)`,
          transform: `scale(${0.7 + 0.5 * cur.scale})`, transition: 'transform 0.1s linear', pointerEvents: 'none'
        }} />
        {/* faint guide ring */}
        <svg width={box} height={box} viewBox="0 0 128 128" style={{ position: 'absolute', transform: 'rotate(-90deg)' }}>
          <circle cx="64" cy="64" r={R} fill="none" stroke="var(--w-line)" strokeWidth="2.5" />
          <circle cx="64" cy="64" r={R} fill="none" stroke={fg} strokeWidth="3.5" strokeLinecap="round"
            strokeDasharray={CC} strokeDashoffset={ringOffset} opacity="0.9"
            style={{ transition: 'stroke-dashoffset 0.1s linear' }} />
        </svg>
        {/* breathing orb */}
        <div style={{
          width: 92 * s, height: 92 * s, borderRadius: '50%',
          background: `radial-gradient(circle at 38% 32%, ${lighten(fg, 0.34)}, ${fg})`,
          transform: `scale(${sc})`, transition: 'transform 0.1s linear',
          boxShadow: `0 ${10 * s}px ${28 * s}px ${fg}3d`,
          display: 'grid', placeItems: 'center'
        }}>
          <span style={{ fontSize: 26 * s, fontWeight: 700, color: onColor(fg), fontVariantNumeric: 'tabular-nums', lineHeight: 1, opacity: cur.remain > 0 ? 1 : 0.85 }}>
            {cur.remain || ''}
          </span>
        </div>
      </div>

      {showLabel && (
        <div style={{ fontSize: 15 * s, fontWeight: 600, letterSpacing: '0.04em', color: 'var(--w-fg)', minHeight: 18 * s }}>
          {running ? cur.phase.label : (pausedAt > 0 ? 'Paused' : 'Ready')}
        </div>
      )}

      {!mini && (
        <div style={{ display: 'flex', gap: 9 * s, alignItems: 'center' }}>
          <button onClick={running ? pause : start} style={{
            height: 34 * s, padding: `0 ${18 * s}px`, borderRadius: 99, border: 'none', cursor: 'pointer',
            background: fg, color: onColor(fg), fontSize: 13 * s, fontWeight: 600, fontFamily: fontStack
          }}>{running ? 'Pause' : (pausedAt > 0 ? 'Resume' : 'Start')}</button>
          <button onClick={reset} title="Reset" style={{
            height: 34 * s, width: 34 * s, display: 'grid', placeItems: 'center', borderRadius: 99, cursor: 'pointer',
            background: 'transparent', border: '1.5px solid var(--w-line)', color: 'var(--w-mut)'
          }}>
            <svg width={15 * s} height={15 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M3 12a9 9 0 1 0 3-6.7L3 8" /><path d="M3 3v5h5" />
            </svg>
          </button>
        </div>
      )}
    </div>
  );
}

function ButtonGridW({ config: c, accent, s, fontStack, mini }) {
  const ICONS = ['rocket', 'inbox', 'book', 'folder', 'calendar', 'globe', 'compass', 'bolt', 'chart', 'wallet', 'music', 'camera', 'coffee', 'palette', 'code', 'bell', 'star', 'heart', 'home', 'gem', 'flag', 'tag', 'bookmark', 'lightbulb'];
  const fallback = useMemo(() => [
    { label: 'Mail', url: 'https://', icon: 'inbox' },
    { label: 'Docs', url: 'https://', icon: 'book' },
    { label: 'Calendar', url: 'https://', icon: 'calendar' }
  ], []);
  const cfgButtons = Array.isArray(c.buttons) && c.buttons.length ? c.buttons : fallback;
  const cols = Math.max(1, Math.min(6, c.columns || 3));
  const radius = c.radius == null ? 14 : c.radius;
  const layout = c.layout || 'tile';

  const safeIcon = (name) => ICONS.indexOf(name) >= 0 ? name : 'rocket';
  const cleanUrl = (u) => {
    if (!u) return null;
    let t = String(u).trim();
    if (!t || t === 'https://' || t === 'http://') return null;
    if (!/^https?:\/\//i.test(t)) t = 'https://' + t;
    return t;
  };
  const open = (u) => { const t = cleanUrl(u); if (t) { try { window.open(t, '_blank', 'noopener'); } catch (e) {} } };
  const hostOf = (u) => { try { return new URL(cleanUrl(u)).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };

  const [hover, setHover] = useState(-1);
  const list = mini ? cfgButtons.slice(0, cols * 2) : cfgButtons;

  const Tile = (b, i) => {
    const active = hover === i;
    const live = !!cleanUrl(b.url);
    const isList = layout === 'list';
    return (
      <button
        key={i}
        onClick={() => open(b.url)}
        onMouseEnter={() => setHover(i)}
        onMouseLeave={() => setHover(-1)}
        title={cleanUrl(b.url) || b.label}
        style={{
          position: 'relative',
          display: 'flex',
          flexDirection: isList ? 'row' : 'column',
          alignItems: 'center',
          justifyContent: isList ? 'flex-start' : 'center',
          gap: isList ? 12 * s : 9 * s,
          padding: isList ? `${11 * s}px ${13 * s}px` : `${15 * s}px ${10 * s}px`,
          borderRadius: radius * s,
          border: '1px solid var(--w-line)',
          background: active ? lighten(accent, 0.86) : 'var(--w-card, transparent)',
          cursor: live ? 'pointer' : 'default',
          textAlign: isList ? 'left' : 'center',
          transition: 'background 0.16s ease, border-color 0.16s ease, transform 0.16s ease',
          borderColor: active ? lighten(accent, 0.4) : 'var(--w-line)',
          transform: active ? 'translateY(-1px)' : 'none',
          overflow: 'hidden',
          minWidth: 0
        }}
      >
        <span style={{
          flexShrink: 0,
          width: (isList ? 36 : 42) * s,
          height: (isList ? 36 : 42) * s,
          borderRadius: (radius - 4) * s,
          display: 'grid',
          placeItems: 'center',
          background: active ? accent : lighten(accent, 0.82),
          transition: 'background 0.16s ease'
        }}>
          <Icon name={safeIcon(b.icon)} color={active ? onColor(accent) : accent} variant="outline" size={(isList ? 20 : 23) * s} />
        </span>
        <span style={{ display: 'flex', flexDirection: 'column', gap: 2 * s, minWidth: 0, alignItems: isList ? 'flex-start' : 'center' }}>
          <span style={{
            fontSize: (isList ? 13.5 : 12.5) * s,
            fontWeight: 600,
            color: 'var(--w-fg)',
            letterSpacing: '-0.01em',
            maxWidth: '100%',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            lineHeight: 1.15
          }}>{b.label || 'Untitled'}</span>
          {isList && hostOf(b.url) ? <span style={{ fontSize: 11 * s, color: 'var(--w-mut)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: '100%' }}>{hostOf(b.url)}</span> : null}
        </span>
        {isList ? (
          <span style={{ marginLeft: 'auto', flexShrink: 0, opacity: active ? 1 : 0.35, transition: 'opacity 0.16s ease' }}>
            <svg width={15 * s} height={15 * s} viewBox="0 0 24 24" fill="none" stroke="var(--w-mut)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 6l6 6-6 6" /></svg>
          </span>
        ) : null}
      </button>
    );
  };

  return (
    <div style={{ height: '100%', width: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 12 * s, padding: 18 * s, fontFamily: fontStack, boxSizing: 'border-box' }}>
      {c.title ? (
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 * s, paddingInline: 2 * s }}>
          <span style={{ fontSize: 13 * s, fontWeight: 700, color: 'var(--w-fg)', letterSpacing: '-0.01em' }}>{c.title}</span>
          <span style={{ fontSize: 10.5 * s, fontWeight: 600, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)' }}>{list.length}</span>
        </div>
      ) : null}
      {layout === 'list' ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 * s }}>
          {list.map((b, i) => Tile(b, i))}
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`, gap: 10 * s }}>
          {list.map((b, i) => Tile(b, i))}
        </div>
      )}
    </div>
  );
}

function CalculatorW({ config: c, accent, s, fontStack, mini }) {
  const mode = c.mode || 'basic';
  const precision = typeof c.precision === 'number' ? c.precision : 2;

  const round = (n) => {
    if (!isFinite(n)) return '0';
    const p = Math.pow(10, precision);
    let r = Math.round((n + Number.EPSILON) * p) / p;
    if (Object.is(r, -0)) r = 0;
    let str = r.toFixed(precision);
    if (precision > 0) str = str.replace(/\.?0+$/, '');
    return str;
  };

  const fmtNum = (str) => {
    if (str === '' || str === '-') return str;
    const neg = str.startsWith('-');
    let body = neg ? str.slice(1) : str;
    const [intPart, decPart] = body.split('.');
    const withSep = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return (neg ? '-' : '') + withSep + (decPart !== undefined ? '.' + decPart : '');
  };

  // ---- BASIC CALCULATOR ----
  function Basic() {
    const [acc, setAcc] = useState(null);
    const [op, setOp] = useState(null);
    const [cur, setCur] = useState('0');
    const [fresh, setFresh] = useState(true);
    const [hist, setHist] = useState('');

    const compute = (a, b, o) => {
      a = parseFloat(a); b = parseFloat(b);
      if (o === '+') return a + b;
      if (o === '-') return a - b;
      if (o === '×') return a * b;
      if (o === '÷') return b === 0 ? NaN : a / b;
      return b;
    };

    const inputDigit = (d) => {
      if (fresh) { setCur(d); setFresh(false); return; }
      if (cur === '0') { setCur(d); return; }
      if (cur.replace(/[-.]/g, '').length >= 12) return;
      setCur(cur + d);
    };
    const inputDot = () => {
      if (fresh) { setCur('0.'); setFresh(false); return; }
      if (!cur.includes('.')) setCur(cur + '.');
    };
    const toggleSign = () => {
      if (cur === '0' || cur === 'Error') return;
      setCur(cur.startsWith('-') ? cur.slice(1) : '-' + cur);
    };
    const percent = () => {
      const v = parseFloat(cur) / 100;
      setCur(round(v)); setFresh(true);
    };
    const clearAll = () => { setAcc(null); setOp(null); setCur('0'); setFresh(true); setHist(''); };
    const del = () => {
      if (fresh || cur === 'Error') return;
      if (cur.length <= 1 || (cur.length === 2 && cur.startsWith('-'))) { setCur('0'); return; }
      setCur(cur.slice(0, -1));
    };
    const chooseOp = (o) => {
      if (cur === 'Error') return;
      if (op !== null && !fresh && acc !== null) {
        const r = compute(acc, cur, op);
        if (!isFinite(r)) { clearAll(); setCur('Error'); return; }
        const rr = round(r);
        setAcc(rr); setCur(rr); setHist(fmtNum(rr) + ' ' + o);
      } else {
        setAcc(cur); setHist(fmtNum(cur) + ' ' + o);
      }
      setOp(o); setFresh(true);
    };
    const equals = () => {
      if (op === null || acc === null) return;
      const r = compute(acc, cur, op);
      if (!isFinite(r)) { clearAll(); setCur('Error'); return; }
      const rr = round(r);
      setHist(fmtNum(acc) + ' ' + op + ' ' + fmtNum(cur) + ' =');
      setCur(rr); setAcc(null); setOp(null); setFresh(true);
    };

    const Key = ({ label, on, kind, span }) => {
      const isAcc = kind === 'op' || kind === 'eq';
      const bg = kind === 'eq' ? accent : kind === 'op' ? lighten(accent, 0.86) : 'var(--w-line)';
      const fg = kind === 'eq' ? onColor(accent) : kind === 'op' ? accent : 'var(--w-fg)';
      const active = kind === 'op' && op === label && fresh;
      return (
        <button onClick={on} style={{
          gridColumn: span ? 'span 2' : 'auto',
          height: 46 * s, borderRadius: 12 * s, border: 'none', cursor: 'pointer',
          background: active ? accent : kind === 'fn' ? 'transparent' : bg,
          color: active ? onColor(accent) : kind === 'fn' ? 'var(--w-mut)' : fg,
          fontSize: 18 * s, fontWeight: kind === 'fn' ? 500 : 600,
          fontFamily: fontStack, fontVariantNumeric: 'tabular-nums',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          transition: 'background 0.12s, color 0.12s', WebkitTapHighlightColor: 'transparent',
        }}>{label}</button>
      );
    };

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 12 * s }}>
        <div style={{ minHeight: 56 * s, display: 'flex', flexDirection: 'column', alignItems: 'flex-end', justifyContent: 'flex-end', gap: 3 * s, padding: `0 ${4 * s}px` }}>
          <div style={{ fontSize: 12.5 * s, color: 'var(--w-mut)', fontVariantNumeric: 'tabular-nums', minHeight: 15 * s, letterSpacing: '0.01em' }}>{hist}</div>
          <div style={{ fontSize: 38 * s, fontWeight: 600, letterSpacing: '-0.02em', lineHeight: 1.05, fontVariantNumeric: 'tabular-nums', color: cur === 'Error' ? accent : 'var(--w-fg)', maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{cur === 'Error' ? 'Error' : fmtNum(cur)}</div>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 7 * s }}>
          <Key label="AC" kind="fn" on={clearAll} />
          <Key label="±" kind="fn" on={toggleSign} />
          <Key label="%" kind="fn" on={percent} />
          <Key label="÷" kind="op" on={() => chooseOp('÷')} />
          <Key label="7" on={() => inputDigit('7')} />
          <Key label="8" on={() => inputDigit('8')} />
          <Key label="9" on={() => inputDigit('9')} />
          <Key label="×" kind="op" on={() => chooseOp('×')} />
          <Key label="4" on={() => inputDigit('4')} />
          <Key label="5" on={() => inputDigit('5')} />
          <Key label="6" on={() => inputDigit('6')} />
          <Key label="−" kind="op" on={() => chooseOp('-')} />
          <Key label="1" on={() => inputDigit('1')} />
          <Key label="2" on={() => inputDigit('2')} />
          <Key label="3" on={() => inputDigit('3')} />
          <Key label="+" kind="op" on={() => chooseOp('+')} />
          <Key label="0" span on={() => inputDigit('0')} />
          <Key label="." on={inputDot} />
          <Key label="=" kind="eq" on={equals} />
        </div>
      </div>
    );
  }

  // ---- PERCENTAGE ----
  function Percent() {
    const [pct, setPct] = useState('15');
    const [base, setBase] = useState('200');
    const p = parseFloat(pct) || 0;
    const b = parseFloat(base) || 0;
    const portion = (p / 100) * b;

    const Field = ({ label, value, onChange, suffix }) => (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 5 * s, flex: 1 }}>
        <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>{label}</div>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s, borderBottom: `1.5px solid var(--w-line)`, paddingBottom: 5 * s }}>
          <input inputMode="decimal" value={value} onChange={(e) => onChange(e.target.value.replace(/[^0-9.]/g, ''))} style={{ width: '100%', border: 'none', outline: 'none', background: 'transparent', color: 'var(--w-fg)', fontSize: 26 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em', minWidth: 0, padding: 0 }} />
          <span style={{ fontSize: 15 * s, color: 'var(--w-mut)', fontWeight: 600 }}>{suffix}</span>
        </div>
      </div>
    );

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 22 * s }}>
        <div style={{ display: 'flex', gap: 18 * s }}>
          <Field label="Percent" value={pct} onChange={setPct} suffix="%" />
          <Field label="Of" value={base} onChange={setBase} suffix="" />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 * s, padding: `${16 * s}px 0`, borderRadius: 14 * s, background: lighten(accent, 0.9) }}>
          <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Result</div>
          <div style={{ fontSize: 40 * s, fontWeight: 700, color: accent, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>{fmtNum(round(portion))}</div>
        </div>
      </div>
    );
  }

  // ---- TIP ----
  function Tip() {
    const [bill, setBill] = useState('48.00');
    const [tip, setTip] = useState(c.defaultTip != null ? c.defaultTip : 18);
    const [split, setSplit] = useState(1);
    const b = parseFloat(bill) || 0;
    const tipAmt = b * (tip / 100);
    const total = b + tipAmt;
    const per = total / split;
    const cur = c.currency || '$';

    const presets = [15, 18, 20, 25];

    const Stat = ({ label, value, big }) => (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: big ? 'flex-start' : 'flex-end', gap: 2 * s, flex: big ? 1 : 'none' }}>
        <div style={{ fontSize: 10 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>{label}</div>
        <div style={{ fontSize: (big ? 30 : 16) * s, fontWeight: big ? 700 : 600, color: big ? accent : 'var(--w-fg)', lineHeight: 1, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em' }}>{cur}{fmtNum(round(value))}</div>
      </div>
    );

    return (
      <div style={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 16 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5 * s }}>
          <div style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Bill</div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s, borderBottom: `1.5px solid var(--w-line)`, paddingBottom: 5 * s }}>
            <span style={{ fontSize: 22 * s, color: 'var(--w-mut)', fontWeight: 600 }}>{cur}</span>
            <input inputMode="decimal" value={bill} onChange={(e) => setBill(e.target.value.replace(/[^0-9.]/g, ''))} style={{ width: '100%', border: 'none', outline: 'none', background: 'transparent', color: 'var(--w-fg)', fontSize: 28 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.01em', minWidth: 0, padding: 0 }} />
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 7 * s }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Tip</span>
            <span style={{ fontSize: 13 * s, fontWeight: 700, color: accent, fontVariantNumeric: 'tabular-nums' }}>{tip}%</span>
          </div>
          <div style={{ display: 'flex', gap: 6 * s }}>
            {presets.map((pp) => {
              const on = tip === pp;
              return (
                <button key={pp} onClick={() => setTip(pp)} style={{ flex: 1, height: 34 * s, borderRadius: 9 * s, border: `1.5px solid ${on ? accent : 'var(--w-line)'}`, background: on ? accent : 'transparent', color: on ? onColor(accent) : 'var(--w-fg)', fontSize: 13 * s, fontWeight: 600, fontFamily: fontStack, cursor: 'pointer', fontVariantNumeric: 'tabular-nums', transition: 'all 0.12s' }}>{pp}%</button>
              );
            })}
          </div>
        </div>

        {!mini ? (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: 10.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>Split</span>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 * s }}>
              <button onClick={() => setSplit((v) => Math.max(1, v - 1))} style={{ width: 28 * s, height: 28 * s, borderRadius: 8 * s, border: `1.5px solid var(--w-line)`, background: 'transparent', color: 'var(--w-fg)', fontSize: 18 * s, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 1 }}>−</button>
              <span style={{ fontSize: 17 * s, fontWeight: 700, minWidth: 18 * s, textAlign: 'center', fontVariantNumeric: 'tabular-nums' }}>{split}</span>
              <button onClick={() => setSplit((v) => Math.min(50, v + 1))} style={{ width: 28 * s, height: 28 * s, borderRadius: 8 * s, border: `1.5px solid var(--w-line)`, background: 'transparent', color: 'var(--w-fg)', fontSize: 18 * s, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 1 }}>+</button>
            </div>
          </div>
        ) : null}

        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 10 * s, padding: `${14 * s}px ${14 * s}px`, borderRadius: 14 * s, background: lighten(accent, 0.9) }}>
          <Stat label={split > 1 ? 'Per person' : 'Total'} value={per} big />
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 * s, alignItems: 'flex-end' }}>
            <Stat label="Tip" value={tipAmt} />
            {split > 1 ? <Stat label="Total" value={total} /> : null}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', padding: 18 * s, fontFamily: fontStack, boxSizing: 'border-box' }}>
      {mode === 'percent' ? <Percent /> : mode === 'tip' ? <Tip /> : <Basic />}
    </div>
  );
}

function CalorieRingW({ config: c, accent, s, fontStack, mini }) {
  const goal = Math.max(1, +c.goal || 2200);
  const consumed = Math.max(0, +c.consumed || 0);
  const carbs = Math.max(0, +c.carbs || 0);
  const protein = Math.max(0, +c.protein || 0);
  const fat = Math.max(0, +c.fat || 0);

  const remaining = goal - consumed;
  const pct = Math.min(1, consumed / goal);
  const over = consumed > goal;

  const R = 54, C = 2 * Math.PI * R;
  const trackColor = 'var(--w-line)';

  const carbColor = accent;
  const proteinColor = lighten(accent, 0.28);
  const fatColor = lighten(accent, 0.52);

  const macros = [
    { key: 'carbs', label: 'Carbs', grams: carbs, col: carbColor },
    { key: 'protein', label: 'Protein', grams: protein, col: proteinColor },
    { key: 'fat', label: 'Fat', grams: fat, col: fatColor },
  ];
  const macroTotal = Math.max(1, carbs + protein + fat);

  const Macro = ({ label, grams, col }) => {
    const frac = grams / macroTotal;
    return (
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 5 * s, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s }}>
          <span style={{ width: 7 * s, height: 7 * s, borderRadius: 99, background: col, flexShrink: 0 }} />
          <span style={{ fontSize: 9.5 * s, letterSpacing: '0.06em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
        </div>
        <div style={{ fontSize: 16 * s, fontWeight: 700, lineHeight: 1, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.02em' }}>
          {grams}<span style={{ fontSize: 10 * s, fontWeight: 500, color: 'var(--w-mut)', marginLeft: 1.5 * s }}>g</span>
        </div>
        <div style={{ height: 3 * s, borderRadius: 99, background: 'var(--w-line)', overflow: 'hidden' }}>
          <div style={{ height: '100%', width: (frac * 100) + '%', background: col, borderRadius: 99, transition: 'width 0.6s ease' }} />
        </div>
      </div>
    );
  };

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 18 * s, padding: 20 * s, fontFamily: fontStack }}>
      <div style={{ position: 'relative', width: 132 * s, height: 132 * s, flexShrink: 0 }}>
        <svg width={132 * s} height={132 * s} viewBox="0 0 132 132" style={{ transform: 'rotate(-90deg)' }}>
          <circle cx="66" cy="66" r={R} fill="none" stroke={trackColor} strokeWidth={11} />
          <circle
            cx="66" cy="66" r={R} fill="none"
            stroke={over ? lighten(accent, 0.12) : accent}
            strokeWidth={11}
            strokeLinecap="round"
            strokeDasharray={C}
            strokeDashoffset={C * (1 - pct)}
            style={{ transition: 'stroke-dashoffset 0.9s cubic-bezier(0.4,0,0.2,1)' }}
          />
        </svg>
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 1 * s }}>
          <div style={{ fontSize: 30 * s, fontWeight: 700, lineHeight: 1, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.03em', color: over ? accent : 'var(--w-fg)' }}>
            {Math.abs(remaining).toLocaleString()}
          </div>
          <div style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>
            {over ? 'over' : 'left'}
          </div>
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'baseline', gap: 5 * s, fontVariantNumeric: 'tabular-nums' }}>
        <span style={{ fontSize: 13.5 * s, fontWeight: 700, color: 'var(--w-fg)' }}>{consumed.toLocaleString()}</span>
        <span style={{ fontSize: 12 * s, color: 'var(--w-mut)' }}>of {goal.toLocaleString()} kcal</span>
      </div>

      <div style={{ width: '100%', height: 1, background: 'var(--w-line)' }} />

      <div style={{ display: 'flex', width: '100%', gap: 14 * s }}>
        {macros.map(m => <Macro key={m.key} label={m.label} grams={m.grams} col={m.col} />)}
      </div>
    </div>
  );
}

function ContentCalendarW({ config: c, accent, s, fontStack, mini }) {
  const now = useNow(true, 60000);
  const weekStart = c.weekStart === 'Sun' ? 0 : 1;
  const PLATFORMS = useMemo(() => {
    const def = { instagram: '#E1306C', youtube: '#FF0000', tiktok: '#000000', x: '#1DA1F2', linkedin: '#0A66C2', blog: accent, newsletter: '#F59E0B' };
    const cust = (c.platformColors && typeof c.platformColors === 'object') ? c.platformColors : {};
    return { ...def, ...cust };
  }, [c.platformColors, accent]);

  const entries = useMemo(() => Array.isArray(c.entries) ? c.entries : [], [c.entries]);

  const [view, setView] = useState(() => ({ y: now.getFullYear(), m: now.getMonth() }));
  const [selDay, setSelDay] = useState(null);

  const todayKey = fmtKey(now.getFullYear(), now.getMonth(), now.getDate());

  function fmtKey(y, m, d) { return y + '-' + String(m + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0'); }
  function platColor(p) { return PLATFORMS[(p || '').toLowerCase()] || accent; }

  const byDate = useMemo(() => {
    const map = {};
    entries.forEach((e) => {
      if (!e || !e.date) return;
      (map[e.date] = map[e.date] || []).push(e);
    });
    return map;
  }, [entries]);

  const grid = useMemo(() => {
    const first = new Date(view.y, view.m, 1);
    const startDow = (first.getDay() - weekStart + 7) % 7;
    const daysIn = new Date(view.y, view.m + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < startDow; i++) cells.push(null);
    for (let d = 1; d <= daysIn; d++) cells.push(d);
    while (cells.length % 7 !== 0) cells.push(null);
    return cells;
  }, [view, weekStart]);

  const dows = useMemo(() => {
    const base = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
    const out = [];
    for (let i = 0; i < 7; i++) out.push(base[(i + weekStart) % 7]);
    return out;
  }, [weekStart]);

  const monthName = new Date(view.y, view.m, 1).toLocaleString('en-US', { month: 'long' });

  const monthEntries = useMemo(() => {
    const prefix = view.y + '-' + String(view.m + 1).padStart(2, '0');
    return entries.filter((e) => e && e.date && e.date.startsWith(prefix));
  }, [entries, view]);

  const activePlatforms = useMemo(() => {
    const set = [];
    monthEntries.forEach((e) => { const p = (e.platform || '').toLowerCase(); if (p && set.indexOf(p) < 0) set.push(p); });
    return set;
  }, [monthEntries]);

  const publishedCount = monthEntries.filter((e) => e.status === 'published').length;

  function shift(dir) {
    setSelDay(null);
    setView((v) => {
      let m = v.m + dir, y = v.y;
      if (m < 0) { m = 11; y--; } else if (m > 11) { m = 0; y++; }
      return { y, m };
    });
  }

  const selEntries = selDay ? (byDate[selDay] || []) : null;

  function statusDot(e, sz) {
    const col = platColor(e.platform);
    const pub = e.status === 'published';
    return (
      <span style={{ width: sz, height: sz, borderRadius: 99, background: pub ? col : 'transparent', border: '1.5px solid ' + col, boxSizing: 'border-box', flex: '0 0 auto' }} />
    );
  }

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 10 * s, padding: 16 * s }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1 * s }}>
          <div style={{ fontSize: 15 * s, fontWeight: 700, letterSpacing: '-0.01em', lineHeight: 1.1 }}>{monthName} <span style={{ color: 'var(--w-mut)', fontWeight: 600 }}>{view.y}</span></div>
          <div style={{ fontSize: 10.5 * s, color: 'var(--w-mut)', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{monthEntries.length} post{monthEntries.length === 1 ? '' : 's'} · {publishedCount} live</div>
        </div>
        {!mini && (
          <div style={{ display: 'flex', gap: 4 * s }}>
            <button onClick={() => shift(-1)} aria-label="Previous month" style={{ width: 26 * s, height: 26 * s, display: 'grid', placeItems: 'center', borderRadius: 7 * s, border: '1px solid var(--w-line)', background: 'transparent', color: 'var(--w-fg)', cursor: 'pointer' }}>
              <svg width={12 * s} height={12 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M15 6l-6 6 6 6" /></svg>
            </button>
            <button onClick={() => shift(1)} aria-label="Next month" style={{ width: 26 * s, height: 26 * s, display: 'grid', placeItems: 'center', borderRadius: 7 * s, border: '1px solid var(--w-line)', background: 'transparent', color: 'var(--w-fg)', cursor: 'pointer' }}>
              <svg width={12 * s} height={12 * s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M9 6l6 6-6 6" /></svg>
            </button>
          </div>
        )}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 * s }}>
        {dows.map((dl, i) => (
          <div key={'h' + i} style={{ textAlign: 'center', fontSize: 9 * s, fontWeight: 700, letterSpacing: '0.04em', textTransform: 'uppercase', color: 'var(--w-mut)', paddingBottom: 2 * s }}>{dl}</div>
        ))}
        {grid.map((d, i) => {
          if (d === null) return <div key={'e' + i} />;
          const key = fmtKey(view.y, view.m, d);
          const items = byDate[key] || [];
          const isToday = key === todayKey;
          const isSel = key === selDay;
          const shown = items.slice(0, 3);
          const extra = items.length - shown.length;
          return (
            <button
              key={'d' + i}
              onClick={() => { if (mini) return; setSelDay(isSel ? null : (items.length ? key : null)); }}
              style={{
                position: 'relative', aspectRatio: '1 / 1', minHeight: 26 * s,
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 3 * s,
                borderRadius: 7 * s, border: isSel ? ('1.5px solid ' + accent) : '1.5px solid transparent',
                background: isToday ? accent : (items.length ? 'var(--w-line)' : 'transparent'),
                cursor: (!mini && items.length) ? 'pointer' : 'default', padding: 0, boxSizing: 'border-box',
                transition: 'background 0.15s, border-color 0.15s'
              }}
            >
              <span style={{ fontSize: 11 * s, fontWeight: isToday ? 700 : 600, lineHeight: 1, color: isToday ? onColor(accent) : 'var(--w-fg)', fontVariantNumeric: 'tabular-nums' }}>{d}</span>
              {items.length > 0 && (
                <span style={{ display: 'flex', alignItems: 'center', gap: 2.5 * s, height: 6 * s }}>
                  {shown.map((e, k) => (
                    <span key={k} style={{ width: 5 * s, height: 5 * s, borderRadius: 99, background: e.status === 'published' ? platColor(e.platform) : 'transparent', border: (1 * s) + 'px solid ' + (isToday ? onColor(accent) : platColor(e.platform)), boxSizing: 'border-box' }} />
                  ))}
                  {extra > 0 && <span style={{ fontSize: 7 * s, fontWeight: 700, color: isToday ? onColor(accent) : 'var(--w-mut)', lineHeight: 1 }}>+{extra}</span>}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {!mini && selEntries && selEntries.length > 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5 * s, paddingTop: 2 * s, borderTop: '1px solid var(--w-line)' }}>
          {selEntries.slice(0, 3).map((e, i) => (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 7 * s }}>
              {statusDot(e, 8 * s)}
              <span style={{ fontSize: 11.5 * s, fontWeight: 600, color: 'var(--w-fg)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', flex: 1 }}>{e.title || 'Untitled'}</span>
              <span style={{ fontSize: 9 * s, fontWeight: 700, letterSpacing: '0.03em', textTransform: 'uppercase', color: 'var(--w-mut)', flex: '0 0 auto' }}>{e.status === 'published' ? 'Live' : 'Planned'}</span>
            </div>
          ))}
          {selEntries.length > 3 && <span style={{ fontSize: 10 * s, color: 'var(--w-mut)', fontWeight: 600 }}>+{selEntries.length - 3} more</span>}
        </div>
      ) : (
        activePlatforms.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8 * s, paddingTop: 2 * s, borderTop: '1px solid var(--w-line)' }}>
            {activePlatforms.slice(0, 5).map((p) => (
              <span key={p} style={{ display: 'flex', alignItems: 'center', gap: 4 * s }}>
                <span style={{ width: 7 * s, height: 7 * s, borderRadius: 99, background: platColor(p) }} />
                <span style={{ fontSize: 9.5 * s, fontWeight: 600, color: 'var(--w-mut)', textTransform: 'capitalize' }}>{p}</span>
              </span>
            ))}
          </div>
        )
      )}
    </div>
  );
}

function DebtPayoffW({ config: c, accent, s, fontStack, mini }) {
  const KEY = 'nc_debtPayoff_debts';
  const fallback = [
    { id: 'd1', name: 'Credit Card', balance: 4200, rate: 22.9, min: 90 },
    { id: 'd2', name: 'Car Loan', balance: 8500, rate: 6.4, min: 210 },
    { id: 'd3', name: 'Student Loan', balance: 14200, rate: 4.5, min: 160 },
  ];

  const [debts, setDebts] = useState(() => {
    try {
      const raw = JSON.parse(localStorage.getItem(KEY));
      if (Array.isArray(raw) && raw.length) return raw;
    } catch (e) {}
    return Array.isArray(c.debts) && c.debts.length ? c.debts : fallback;
  });

  useEffect(() => { try { localStorage.setItem(KEY, JSON.stringify(debts)); } catch (e) {} }, [debts]);

  const strategy = c.strategy === 'snowball' ? 'snowball' : 'avalanche';
  const extra = Math.max(0, Number(c.extra) || 0);
  const currency = c.currency || 'USD';

  const symFor = (cur) => ({ USD: '$', EUR: '€', GBP: '£', INR: '₹', JPY: '¥', CAD: '$', AUD: '$' }[cur] || '$');
  const sym = symFor(currency);

  const money = (n) => {
    const v = Math.round(n || 0);
    return sym + v.toLocaleString('en-US');
  };
  const moneyK = (n) => {
    if (n >= 1000) {
      const k = n / 1000;
      return sym + (k >= 10 ? Math.round(k) : k.toFixed(1).replace(/\.0$/, '')) + 'k';
    }
    return sym + Math.round(n);
  };

  // Ordered list per strategy. Snowball: smallest balance first. Avalanche: highest rate first.
  const ordered = useMemo(() => {
    const arr = debts.map((d, i) => ({
      id: d.id || ('d' + i),
      name: d.name || 'Debt',
      balance: Math.max(0, Number(d.balance) || 0),
      rate: Math.max(0, Number(d.rate) || 0),
      min: Math.max(0, Number(d.min) || 0),
    }));
    arr.sort((a, b) => strategy === 'snowball' ? a.balance - b.balance : b.rate - a.rate);
    return arr;
  }, [debts, strategy]);

  // Simulate month-by-month payoff with rollover (the "snowball/avalanche" engine).
  const sim = useMemo(() => {
    const list = ordered.map(d => ({ ...d, bal: d.balance, paidOff: null }));
    const totalMin = list.reduce((s2, d) => s2 + d.min, 0);
    let pool = totalMin + extra;
    let month = 0;
    let totalInterest = 0;
    const cap = 1200; // 100 years guard
    const active = () => list.filter(d => d.bal > 0.01);

    while (active().length && month < cap) {
      month++;
      let budget = pool;
      // accrue interest
      for (const d of list) {
        if (d.bal > 0.01) {
          const i = d.bal * (d.rate / 100) / 12;
          d.bal += i;
          totalInterest += i;
        }
      }
      // pay minimums first (in priority order so freed budget rolls forward)
      for (const d of list) {
        if (d.bal <= 0.01 || budget <= 0) continue;
        const pay = Math.min(d.min, d.bal, budget);
        d.bal -= pay; budget -= pay;
      }
      // throw remaining budget at the top-priority active debt
      let guard = 0;
      while (budget > 0.01 && active().length && guard < list.length + 1) {
        guard++;
        const tgt = active()[0];
        const pay = Math.min(budget, tgt.bal);
        tgt.bal -= pay; budget -= pay;
      }
      for (const d of list) {
        if (d.paidOff === null && d.bal <= 0.01) d.paidOff = month;
      }
    }

    const totalStart = list.reduce((s2, d) => s2 + d.balance, 0);
    const remaining = list.reduce((s2, d) => s2 + Math.max(0, d.bal), 0);
    return { list, months: month, totalInterest, totalStart, remaining, totalMin, capped: month >= cap };
  }, [ordered, extra]);

  const payoffDate = useMemo(() => {
    const d = new Date();
    d.setDate(1);
    d.setMonth(d.getMonth() + sim.months);
