            {c.title || 'Debt Free'}
          </div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 * s }}>
            <div style={{ fontSize: 30 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>
              {sim.months === 0 ? 'Done' : fmtMY(payoffDate)}
            </div>
          </div>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 3 * s }}>
          <span style={{ fontSize: 9.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 700 }}>
            {strategy === 'snowball' ? 'Snowball' : 'Avalanche'}
          </span>
          <span style={{ fontSize: 13 * s, fontWeight: 600, color: 'var(--w-fg)', fontVariantNumeric: 'tabular-nums' }}>{durStr}</span>
        </div>
      </div>

      {/* Bars */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 11 * s }}>
        {sim.list.map((d, i) => {
          const w = Math.max(0.04, d.balance / maxBal);
          const isNext = i === 0 && d.balance > 0.01;
          return (
            <div key={d.id} style={{ display: 'flex', flexDirection: 'column', gap: 4 * s }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 8 * s }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 * s, minWidth: 0 }}>
                  {isNext ? (
                    <span style={{ width: 5 * s, height: 5 * s, borderRadius: 99, background: accent, flexShrink: 0 }} />
                  ) : (
                    <span style={{ width: 5 * s, height: 5 * s, borderRadius: 99, background: 'var(--w-line)', flexShrink: 0 }} />
                  )}
                  <span style={{ fontSize: 12.5 * s, fontWeight: isNext ? 700 : 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: 'var(--w-fg)' }}>
                    {d.name}
                  </span>
                  <span style={{ fontSize: 10 * s, color: 'var(--w-mut)', fontVariantNumeric: 'tabular-nums', flexShrink: 0 }}>
                    {d.rate ? d.rate + '%' : ''}
                  </span>
                </div>
                <span style={{ fontSize: 12 * s, fontWeight: 600, fontVariantNumeric: 'tabular-nums', color: 'var(--w-fg)', flexShrink: 0 }}>
                  {money(d.balance)}
                </span>
              </div>
              <div style={{ position: 'relative', height: 7 * s, borderRadius: 99, background: 'var(--w-line)', overflow: 'hidden' }}>
                <div style={{
                  position: 'absolute', inset: 0, width: (w * 100) + '%',
                  borderRadius: 99,
                  background: isNext ? accent : lighten(accent, 0.45),
                  opacity: isNext ? 1 : 0.85,
                  transition: 'width 0.6s ease',
                }} />
              </div>
              {!mini && d.paidOff ? (
                <div style={{ fontSize: 9.5 * s, color: 'var(--w-mut)', fontVariantNumeric: 'tabular-nums' }}>
                  clear by {fmtMY((() => { const dt = new Date(); dt.setDate(1); dt.setMonth(dt.getMonth() + d.paidOff); return dt; })())}
                </div>
              ) : null}
            </div>
          );
        })}
      </div>

      {/* Footer summary */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10 * s, paddingTop: 11 * s, borderTop: '1px solid var(--w-line)' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1 * s }}>
          <span style={{ fontSize: 9 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 700 }}>Total owed</span>
          <span style={{ fontSize: 14 * s, fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{moneyK(sim.totalStart)}</span>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1 * s, alignItems: 'center' }}>
          <span style={{ fontSize: 9 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 700 }}>Per month</span>
          <span style={{ fontSize: 14 * s, fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{moneyK(sim.totalMin + extra)}</span>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1 * s, alignItems: 'flex-end' }}>
          <span style={{ fontSize: 9 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 700 }}>Interest</span>
          <span style={{ fontSize: 14 * s, fontWeight: 700, fontVariantNumeric: 'tabular-nums', color: accent }}>{moneyK(sim.totalInterest)}</span>
        </div>
      </div>
    </div>
  );
}

