  const spArea = spPath + ` L${spW},${spH} L0,${spH} Z`;

  const levelColor = (lv) => lv === 0 ? 'var(--w-line)' : lv === 1 ? lighten(accent, 0.55) : lv === 2 ? lighten(accent, 0.32) : lv === 3 ? lighten(accent, 0.1) : accent;
  const cell = (mini ? 8 : 10) * s, gap = 2 * s;

  const Stat = ({ icon, label, value }) => (
