function HeatmapTrackerW({ config: c, accent, s, fontStack, mini }) {
  const label = c.label || 'Practice';
  const scheme = c.scheme || 'green';
  const levels = Math.max(2, Math.min(5, c.intensity || 4));
  const year = c.year || new Date().getFullYear();

  const baseHue = useMemo(() => {
    const map = { green: '#1F8A5B', blue: '#2563EB', purple: '#7C3AED', orange: '#EA580C', accent: accent };
    return map[scheme] || accent;
  }, [scheme, accent]);

  const storeKey = 'nc_heatmapTracker_' + year + '_' + scheme;
  const [data, setData] = useState(() => {
    try { return JSON.parse(localStorage.getItem(storeKey)) || {}; } catch (e) { return {}; }
  });
  useEffect(() => {
    try { setData(JSON.parse(localStorage.getItem(storeKey)) || {}); } catch (e) { setData({}); }
  }, [storeKey]);
  useEffect(() => {
    try { localStorage.setItem(storeKey, JSON.stringify(data)); } catch (e) {}
  }, [data, storeKey]);

  const [hover, setHover] = useState(null);

  const pad = (n) => (n < 10 ? '0' + n : '' + n);
  const dayKey = (d) => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());

  const grid = useMemo(() => {
    const start = new Date(year, 0, 1);
    const startDow = start.getDay();
    const firstCol = new Date(year, 0, 1 - startDow);
    const end = new Date(year, 11, 31);
    const weeks = [];
    let cur = new Date(firstCol);
    while (cur <= end || weeks.length === 0 || weeks[weeks.length - 1].length < 7) {
      const wi = weeks.length - 1;
      if (weeks.length === 0 || weeks[wi].length === 7) weeks.push([]);
      const col = weeks[weeks.length - 1];
      const inYear = cur.getFullYear() === year;
      col.push({
        key: dayKey(cur),
        inYear,
        month: cur.getMonth(),
        date: cur.getDate(),
        firstOfMonth: cur.getDate() === 1,
      });
      cur.setDate(cur.getDate() + 1);
      if (cur > end && weeks[weeks.length - 1].length === 7) break;
    }
    return weeks;
  }, [year]);

  const monthLabels = useMemo(() => {
    const names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const out = [];
    grid.forEach((week, wi) => {
      const cell = week.find((d) => d.inYear && d.firstOfMonth);
      if (cell) out.push({ col: wi, name: names[cell.month] });
    });
    return out;
  }, [grid]);

  const todayKey = useMemo(() => dayKey(new Date()), []);

  const cellColor = (lvl) => {
    if (lvl <= 0) return 'var(--w-line)';
    const frac = lvl / levels;
    const amt = (1 - frac) * 0.72;
    return lighten(baseHue, amt);
  };

  const cycle = (k) => {
    if (mini) return;
    setData((p) => {
      const next = { ...p };
      const v = (next[k] || 0) + 1;
      if (v > levels) delete next[k]; else next[k] = v;
      return next;
    });
  };

  const stats = useMemo(() => {
    let total = 0, active = 0;
    Object.keys(data).forEach((k) => {
      if (k.indexOf(year + '-') === 0 && data[k] > 0) { total += data[k]; active += 1; }
    });
    let streak = 0;
    let d = new Date();
    if (d.getFullYear() === year) {
      while (true) {
        if (data[dayKey(d)] > 0) { streak += 1; d.setDate(d.getDate() - 1); }
        else break;
        if (d.getFullYear() < year) break;
      }
    }
    return { active, streak };
  }, [data, year]);

  const dows = ['', 'Mon', '', 'Wed', '', 'Fri', ''];
  const GAP = 3 * s;
  const CELL = 11 * s;
  const RAD = 2.5 * s;

  const legend = [];
  for (let i = 0; i <= levels; i++) legend.push(i);

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 12 * s, padding: 18 * s, fontFamily: fontStack }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s }}>
          <div style={{ fontSize: 14.5 * s, fontWeight: 600, color: 'var(--w-fg)' }}>{label}</div>
          <div style={{ fontSize: 11 * s, color: 'var(--w-mut)', fontWeight: 500 }}>{year}</div>
        </div>
        <div style={{ display: 'flex', gap: 14 * s }}>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
            <div style={{ fontSize: 18 * s, fontWeight: 700, lineHeight: 1, color: 'var(--w-fg)', fontVariantNumeric: 'tabular-nums' }}>{stats.active}</div>
            <div style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>days</div>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
            <div style={{ fontSize: 18 * s, fontWeight: 700, lineHeight: 1, color: accent, fontVariantNumeric: 'tabular-nums' }}>{stats.streak}</div>
            <div style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600 }}>streak</div>
          </div>
        </div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: GAP, overflowX: 'auto', overflowY: 'hidden' }}>
        <div style={{ display: 'flex', gap: GAP, paddingLeft: 22 * s, minWidth: 'min-content' }}>
          {grid.map((week, wi) => {
            const ml = monthLabels.find((m) => m.col === wi);
            return (
              <div key={'mh' + wi} style={{ width: CELL, fontSize: 9 * s, color: 'var(--w-mut)', fontWeight: 600, whiteSpace: 'nowrap', overflow: 'visible', height: 11 * s }}>
                {ml ? ml.name : ''}
              </div>
            );
          })}
        </div>

        <div style={{ display: 'flex', gap: GAP, minWidth: 'min-content' }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: GAP, width: 19 * s, flexShrink: 0 }}>
            {dows.map((dl, i) => (
              <div key={'d' + i} style={{ height: CELL, fontSize: 8.5 * s, color: 'var(--w-mut)', fontWeight: 600, display: 'flex', alignItems: 'center', lineHeight: 1 }}>{dl}</div>
            ))}
          </div>
          {grid.map((week, wi) => (
            <div key={'w' + wi} style={{ display: 'flex', flexDirection: 'column', gap: GAP }}>
              {week.map((cell, di) => {
                if (!cell.inYear) return <div key={cell.key + di} style={{ width: CELL, height: CELL }} />;
                const lvl = data[cell.key] || 0;
                const isToday = cell.key === todayKey;
                return (
                  <div
                    key={cell.key}
                    onClick={() => cycle(cell.key)}
                    onMouseEnter={() => setHover({ key: cell.key, lvl })}
                    onMouseLeave={() => setHover(null)}
                    title={cell.key + (lvl ? ' · level ' + lvl : '')}
                    style={{
                      width: CELL,
                      height: CELL,
                      borderRadius: RAD,
                      background: cellColor(lvl),
                      cursor: mini ? 'default' : 'pointer',
                      boxShadow: isToday ? '0 0 0 ' + (1.5 * s) + 'px ' + accent : 'none',
                      transition: 'background 0.15s ease, transform 0.1s ease',
                      transform: hover && hover.key === cell.key ? 'scale(1.18)' : 'scale(1)',
                    }}
                  />
                );
              })}
            </div>
          ))}
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 * s }}>
        <div style={{ fontSize: 10.5 * s, color: 'var(--w-mut)', fontWeight: 500, minHeight: 13 * s }}>
          {hover ? (hover.lvl ? hover.key + ' · ' + hover.lvl + 'x' : hover.key) : (mini ? '' : 'Tap a day to log')}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 * s }}>
          <span style={{ fontSize: 9.5 * s, color: 'var(--w-mut)', fontWeight: 600 }}>Less</span>
          {legend.map((l) => (
            <span key={'lg' + l} style={{ width: 10 * s, height: 10 * s, borderRadius: 2 * s, background: cellColor(l) }} />
          ))}
          <span style={{ fontSize: 9.5 * s, color: 'var(--w-mut)', fontWeight: 600 }}>More</span>
        </div>
      </div>
    </div>
  );
}

function LifeInWeeksW({ config: c, accent, s, fontStack, mini }) {
  const now = useNow(true, 60000);
  const birth = c.birthDate || '1995-06-01';
  const life = Math.max(1, Math.min(120, c.lifeExpectancy || 90));
  const fill = c.filledColor || accent;

  const stats = useMemo(() => {
    const b = new Date(birth + 'T00:00:00');
    const totalWeeks = Math.round(life * 52.1775);
    let lived = Math.floor((now - b) / (7 * 864e5));
    if (isNaN(lived) || lived < 0) lived = 0;
    lived = Math.min(lived, totalWeeks);
    const cols = 52;
    const rows = Math.ceil(totalWeeks / cols);
    const pct = totalWeeks ? lived / totalWeeks : 0;
    const ageYears = Math.max(0, (now - b) / (365.25 * 864e5));
    return { totalWeeks, lived, cols, rows, pct, ageYears, valid: !isNaN(b.getTime()) };
  }, [birth, life, now]);

  if (!stats.valid) {
    return (
      <div style={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 18 * s, fontSize: 13 * s, color: 'var(--w-mut)', fontFamily: fontStack }}>
        Set a birth date
      </div>
    );
  }

  const dot = 5;
  const gap = 1.6;
  const step = dot + gap;
  const gridW = stats.cols * step - gap;
  const gridH = stats.rows * step - gap;
  const muted = c.showMuted !== false;
  const weeksLeft = stats.totalWeeks - stats.lived;
  const fmtN = (n) => n.toLocaleString();

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 13 * s, padding: 18 * s, fontFamily: fontStack, boxSizing: 'border-box' }}>
      <div style={{ width: '100%', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 10 * s }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s, minWidth: 0 }}>
          <div style={{ fontSize: 11 * s, letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--w-mut)', fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{c.title || 'Life in Weeks'}</div>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 5 * s }}>
            <span style={{ fontSize: 24 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums', color: fill }}>{Math.floor(stats.ageYears)}</span>
            <span style={{ fontSize: 11.5 * s, color: 'var(--w-mut)', fontWeight: 500 }}>yrs</span>
          </div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: 17 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums' }}>{Math.round(stats.pct * 100)}%</div>
          <div style={{ fontSize: 10 * s, color: 'var(--w-mut)', fontWeight: 500, marginTop: 2 * s }}>elapsed</div>
        </div>
      </div>

      <svg
        width="100%"
        viewBox={`0 0 ${gridW} ${gridH}`}
        preserveAspectRatio="xMidYMid meet"
        style={{ display: 'block', maxHeight: 180 * s, overflow: 'visible' }}
        shapeRendering="geometricPrecision"
      >
        {Array.from({ length: stats.totalWeeks }).map((_, i) => {
          const col = i % stats.cols;
          const row = Math.floor(i / stats.cols);
          const isFilled = i < stats.lived;
          const isCurrent = i === stats.lived;
          const x = col * step;
          const y = row * step;
          let fillColor, op, sw = 0, stroke = 'none';
          if (isCurrent) {
            fillColor = fill;
            op = 1;
            stroke = onColor(fill) === '#fff' || luminance(fill) < 0.5 ? lighten(fill, 0.4) : fill;
            sw = 0.7;
          } else if (isFilled) {
            fillColor = fill;
            op = 1;
          } else {
            fillColor = 'var(--w-line)';
            op = muted ? 0.55 : 0.9;
          }
          return (
            <rect
              key={i}
              x={x}
              y={y}
              width={dot}
              height={dot}
              rx={1.1}
              fill={fillColor}
              fillOpacity={op}
              stroke={isCurrent ? fill : 'none'}
              strokeWidth={isCurrent ? 0.8 : 0}
            >
              {isCurrent ? <animate attributeName="fill-opacity" values="1;0.4;1" dur="2.4s" repeatCount="indefinite" /> : null}
            </rect>
          );
        })}
      </svg>

      {!mini ? (
        <div style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', fontSize: 10.5 * s, color: 'var(--w-mut)', fontWeight: 500, fontVariantNumeric: 'tabular-nums' }}>
          <span><span style={{ color: 'var(--w-fg)', fontWeight: 600 }}>{fmtN(stats.lived)}</span> lived</span>
          <span style={{ width: 3 * s, height: 3 * s, borderRadius: 99, background: 'var(--w-line)' }} />
          <span><span style={{ color: 'var(--w-fg)', fontWeight: 600 }}>{fmtN(weeksLeft)}</span> ahead</span>
        </div>
      ) : null}
    </div>
  );
}

function MoodTrackerW({ config: c, accent, s, fontStack, mini }) {
  const now = useNow(false, 60000);
  const DEFAULT_MOODS = [
    { emoji: '😀', label: 'Great', color: '#1F8A5B' },
    { emoji: '🙂', label: 'Good', color: '#7BB661' },
    { emoji: '😐', label: 'Okay', color: '#E0A800' },
    { emoji: '😕', label: 'Low', color: '#E07B39' },
    { emoji: '😢', label: 'Bad', color: '#C0455B' },
  ];
  const moods = (Array.isArray(c.moods) && c.moods.length) ? c.moods : DEFAULT_MOODS;
  const view = c.view || 'calendar';
  const title = c.title || 'Mood';

  const key = (d) => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return y + '-' + m + '-' + day;
  };

  const [log, setLog] = useState(() => {
    try { return JSON.parse(localStorage.getItem('nc_moodTracker_log')) || {}; } catch (e) { return {}; }
  });
  useEffect(() => {
    try { localStorage.setItem('nc_moodTracker_log', JSON.stringify(log)); } catch (e) {}
  }, [log]);

  const [cursor, setCursor] = useState(() => { const n = new Date(); return { y: n.getFullYear(), m: n.getMonth() }; });

  const today = useMemo(() => new Date(), [now]);
  const todayKey = key(today);

  const moodByIndex = (i) => moods[i] || null;
  const setMood = (k, idx) => {
    setLog(p => {
      const next = { ...p };
      if (next[k] === idx) delete next[k]; else next[k] = idx;
      return next;
    });
  };

  const monthLabel = useMemo(() => {
    return new Date(cursor.y, cursor.m, 1).toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  }, [cursor]);

  const grid = useMemo(() => {
    const first = new Date(cursor.y, cursor.m, 1);
    const startDow = (first.getDay() + 6) % 7; // Mon=0
    const days = new Date(cursor.y, cursor.m + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < startDow; i++) cells.push(null);
    for (let d = 1; d <= days; d++) cells.push(new Date(cursor.y, cursor.m, d));
    while (cells.length % 7 !== 0) cells.push(null);
    return cells;
  }, [cursor]);

  const stats = useMemo(() => {
    const entries = Object.entries(log);
    const total = entries.length;
    const counts = moods.map(() => 0);
    entries.forEach(([, idx]) => { if (counts[idx] != null) counts[idx]++; });
    // streak: consecutive days ending today (or yesterday)
    let streak = 0;
    const cur = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    if (log[key(cur)] == null) cur.setDate(cur.getDate() - 1);
    while (log[key(cur)] != null) { streak++; cur.setDate(cur.getDate() - 1); }
    return { total, counts, streak };
  }, [log, moods, today]);

  const W = '100%';
  const todayMoodIdx = log[todayKey];

  // ---- TODAY PICKER (shared) ----
