      <div style={{ height: '100%', width: W, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 12 * s, padding: 18 * s, fontFamily: fontStack }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ fontSize: 13.5 * s, fontWeight: 700, letterSpacing: '-0.01em' }}>{monthLabel}</div>
          {!mini && (
