                <button key={dir} onClick={() => setCursor(p => { const m = p.m + dir; return { y: p.y + Math.floor(m / 12), m: ((m % 12) + 12) % 12 }; })}
                  style={{ width: 24 * s, height: 24 * s, borderRadius: 6 * s, display: 'grid', placeItems: 'center', cursor: 'pointer', background: 'transparent', border: '1px solid var(--w-line)', color: 'var(--w-mut)', fontSize: 14 * s, lineHeight: 1 }}>{g}</button>
              ))}
            </div>
          )}
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 4 * s }}>
          {DOW.map((d, i) => (
