          ))}
          {grid.map((d, i) => {
            if (!d) return <div key={'e' + i} />;
            const k = key(d);
            const idx = log[k];
            const mo = idx != null ? moodByIndex(idx) : null;
            const isToday = k === todayKey;
            return (
              <button key={k} title={mo ? mo.label : k}
                onClick={() => { const order = [...moods, null]; const cur = idx == null ? -1 : idx; const nxt = (cur + 1) % moods.length === 0 && idx === moods.length - 1 ? null : (idx == null ? 0 : idx + 1); setLog(p => { const n = { ...p }; if (nxt == null) delete n[k]; else n[k] = nxt; return n; }); }}
                style={{
                  aspectRatio: '1 / 1', borderRadius: 6 * s, cursor: 'pointer', position: 'relative',
