                }}>
                {mo ? <span>{mo.emoji}</span> : (isToday ? <span style={{ width: 4 * s, height: 4 * s, borderRadius: 99, background: accent }} /> : null)}
              </button>
            );
          })}
        </div>

        {!mini && (
          <div style={{ marginTop: 2 * s, paddingTop: 10 * s, borderTop: '1px solid var(--w-line)' }}>
            <Picker />
          </div>
        )}
      </div>
