  // ---- STATS / SUMMARY VIEW ----
  const maxCount = Math.max(1, ...stats.counts);
  return (
    <div style={{ height: '100%', width: W, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 14 * s, padding: 20 * s, fontFamily: fontStack }}>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
        <div style={{ fontSize: 14 * s, fontWeight: 700 }}>{title}</div>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 4 * s, color: 'var(--w-mut)' }}>
          <span style={{ fontSize: 18 * s, fontWeight: 800, color: accent, fontVariantNumeric: 'tabular-nums', lineHeight: 1 }}>{stats.streak}</span>
          <span style={{ fontSize: 10 * s, fontWeight: 600, letterSpacing: '0.04em', textTransform: 'uppercase' }}>day streak</span>
        </div>
      </div>

      <Picker />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 7 * s, marginTop: 2 * s }}>
