            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8 * s }}>
              <span style={{ fontSize: 14 * s, width: 18 * s, textAlign: 'center', flex: '0 0 auto', lineHeight: 1 }}>{mo.emoji}</span>
              <div style={{ flex: 1, height: 8 * s, borderRadius: 99, background: 'var(--w-line)', overflow: 'hidden' }}>
                <div style={{ width: (pct * 100) + '%', height: '100%', borderRadius: 99, background: mo.color, transition: 'width 0.4s ease' }} />
              </div>
              <span style={{ fontSize: 11 * s, fontWeight: 600, color: 'var(--w-mut)', width: 18 * s, textAlign: 'right', flex: '0 0 auto', fontVariantNumeric: 'tabular-nums' }}>{ct}</span>
            </div>
          );
        })}
      </div>

      <div style={{ fontSize: 10.5 * s, color: 'var(--w-mut)', textAlign: 'center', letterSpacing: '0.02em' }}>{stats.total} {stats.total === 1 ? 'day' : 'days'} logged</div>
    </div>
  );
}

