function PostingStreakW({ config: c, accent, s, fontStack, mini }) {
  const resetHour = typeof c.resetHour === 'number' ? c.resetHour : 4;
  const showLongest = c.showLongest !== false;

  // logical "day" key respecting reset hour (a post at 2am counts as previous day)
  const dayKey = (d) => {
    const shifted = new Date(d.getTime() - resetHour * 36e5);
    return Math.floor((shifted.getTime() - shifted.getTimezoneOffset() * 6e4) / 864e5);
  };

  const todayKey = dayKey(new Date());

  // normalize config postDates (array of YYYY-MM-DD or day-keys) into a Set of day-keys
  const seedKeys = useMemo(() => {
    const out = [];
    const arr = Array.isArray(c.postDates) ? c.postDates : [];
    for (const v of arr) {
      if (typeof v === 'number') { out.push(v); continue; }
      const parsed = new Date(v + 'T12:00:00');
      if (!isNaN(parsed)) out.push(dayKey(parsed));
    }
    return out;
  }, [c.postDates, resetHour]);

  const [extra, setExtra] = useState(() => {
    try { return JSON.parse(localStorage.getItem('nc_postingStreak_days')) || []; }
    catch (e) { return []; }
  });
  useEffect(() => {
    try { localStorage.setItem('nc_postingStreak_days', JSON.stringify(extra)); } catch (e) {}
  }, [extra]);

  const days = useMemo(() => {
    const set = new Set();
    seedKeys.forEach(k => set.add(k));
    extra.forEach(k => set.add(k));
    return set;
  }, [seedKeys, extra]);

  const postedToday = days.has(todayKey);

  // current streak: count back from today (or yesterday if not yet posted today)
  const current = useMemo(() => {
    let n = 0;
    let cursor = days.has(todayKey) ? todayKey : todayKey - 1;
    while (days.has(cursor)) { n++; cursor--; }
    return n;
  }, [days, todayKey]);

  // longest streak across all recorded days
  const longest = useMemo(() => {
    const sorted = Array.from(days).sort((a, b) => a - b);
    let best = 0, run = 0, prev = null;
    for (const k of sorted) {
      run = (prev !== null && k === prev + 1) ? run + 1 : 1;
      if (run > best) best = run;
      prev = k;
    }
    return Math.max(best, current);
  }, [days, current]);

  const toggleToday = () => {
    setExtra(prev => {
      if (days.has(todayKey)) {
        // remove today (only possible if it came from extra; seed days are permanent)
        return prev.filter(k => k !== todayKey);
      }
      return prev.includes(todayKey) ? prev : [...prev, todayKey];
    });
  };

  // flame visual intensity grows with streak
  const intensity = Math.min(1, current / 14);
  const flameSize = 60 + intensity * 14;
  const lit = current > 0;
  const flameCore = lit ? accent : 'var(--w-line)';
  const flameOuter = lit ? lighten(accent, 0.18) : 'var(--w-line)';
  const flameInner = lit ? lighten(accent, 0.55) : 'transparent';

  const Stat = ({ value, label, hot }) => (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 * s }}>
      <div style={{
        fontSize: 26 * s, fontWeight: 700, lineHeight: 1,
        letterSpacing: '-0.02em', fontVariantNumeric: 'tabular-nums',
        color: hot ? accent : 'var(--w-fg)'
      }}>{value}</div>
      <div style={{
        fontSize: 9.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase',
        color: 'var(--w-mut)', fontWeight: 600
      }}>{label}</div>
    </div>
  );

  return (
    <div style={{
      height: '100%', display: 'flex', flexDirection: 'column',
      alignItems: 'center', justifyContent: 'center', gap: 14 * s, padding: 18 * s,
      fontFamily: fontStack
    }}>
      <div style={{ position: 'relative', width: flameSize * s, height: (flameSize + 8) * s, display: 'grid', placeItems: 'center' }}>
        {lit ? (
          <div style={{
            position: 'absolute', width: flameSize * 0.78 * s, height: flameSize * 0.78 * s,
            borderRadius: '50%', background: accent, filter: 'blur(' + (16 * s) + 'px)',
            opacity: 0.18 + intensity * 0.22, bottom: flameSize * 0.12 * s
          }} />
        ) : null}
        <svg width={flameSize * s} height={(flameSize + 8) * s} viewBox="0 0 64 72" style={{ position: 'relative' }}>
          <path
            d="M32 2 C42 18 54 24 54 44 C54 60 44 70 32 70 C20 70 10 60 10 44 C10 30 22 26 24 14 C30 22 28 30 36 34 C40 28 38 18 32 2 Z"
            fill={flameOuter}
            opacity={lit ? 0.9 : 0.4}
          />
          <path
            d="M32 20 C40 30 44 36 44 46 C44 56 38 64 32 64 C26 64 20 57 20 47 C20 39 26 37 28 30 C30 36 30 40 35 42 C37 38 36 30 32 20 Z"
            fill={flameCore}
          />
          {lit ? (
            <path
              d="M32 38 C37 44 38 48 38 52 C38 58 35 62 32 62 C29 62 26 58 26 53 C26 48 29 47 30 43 C31 47 32 47 33 47 C34 45 33 42 32 38 Z"
              fill={flameInner}
              opacity={0.55 + intensity * 0.35}
            />
          ) : null}
        </svg>
      </div>

      <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 * s }}>
        <span style={{
          fontSize: 40 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.03em',
          fontVariantNumeric: 'tabular-nums', color: lit ? 'var(--w-fg)' : 'var(--w-mut)'
        }}>{current}</span>
        <span style={{ fontSize: 13 * s, fontWeight: 600, color: 'var(--w-mut)' }}>
          {current === 1 ? 'day' : 'days'}
        </span>
      </div>

      <div style={{
        fontSize: 11 * s, letterSpacing: '0.08em', textTransform: 'uppercase',
        color: 'var(--w-mut)', fontWeight: 600, marginTop: -6 * s
      }}>
        {lit ? 'current streak' : 'start your streak'}
      </div>

      {showLongest ? (
        <div style={{
          display: 'flex', alignItems: 'center', gap: 16 * s,
          paddingTop: 12 * s, borderTop: '1px solid var(--w-line)', width: '100%',
          justifyContent: 'center'
        }}>
          <Stat value={current} label="current" hot={lit} />
          <div style={{ width: 1, height: 26 * s, background: 'var(--w-line)' }} />
          <Stat value={longest} label="longest" />
        </div>
      ) : null}

      {!mini ? (
        <button
          onClick={toggleToday}
          style={{
            height: 34 * s, padding: '0 ' + (16 * s) + 'px', borderRadius: 8 * s,
            background: postedToday ? 'transparent' : accent,
            color: postedToday ? 'var(--w-fg)' : onColor(accent),
            border: postedToday ? '1px solid var(--w-line)' : 'none',
            fontSize: 12.5 * s, fontWeight: 600, cursor: 'pointer',
            display: 'inline-flex', alignItems: 'center', gap: 6 * s, marginTop: 2 * s,
            fontFamily: fontStack
          }}
        >
          {postedToday ? 'Posted today' : 'Mark today'}
        </button>
      ) : null}
    </div>
  );
}

function SleepTrackerW({ config: c, accent, s, fontStack, mini }) {
  const goal = Math.max(1, c.goalHours || 8);
  const showDebt = c.showDebt !== false;
  const KEY = 'nc_sleepTracker_log';

  const defBed = c.bedtime || '23:00';
  const defWake = c.wakeTime || '07:00';

  const [log, setLog] = useState(() => {
    try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch (e) { return {}; }
  });
  useEffect(() => { try { localStorage.setItem(KEY, JSON.stringify(log)); } catch (e) {} }, [log]);

  const [bed, setBed] = useState(defBed);
  const [wake, setWake] = useState(defWake);

  const toMin = (t) => { const p = (t || '0:0').split(':'); return (+p[0]) * 60 + (+p[1]); };
  const dur = (b, w) => { let d = toMin(w) - toMin(b); if (d <= 0) d += 1440; return d; };

  const keyFor = (offset) => {
    const dt = new Date(); dt.setDate(dt.getDate() - offset);
    return dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0') + '-' + String(dt.getDate()).padStart(2, '0');
  };
  const dayLetters = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  const last7 = useMemo(() => {
    const arr = [];
    for (let i = 6; i >= 0; i--) {
      const k = keyFor(i);
      const dt = new Date(); dt.setDate(dt.getDate() - i);
      const rec = log[k];
      arr.push({ k, dow: dt.getDay(), mins: rec ? dur(rec.b, rec.w) : null, today: i === 0 });
    }
    return arr;
  }, [log]);

  const goalMin = goal * 60;
  const todayKey = keyFor(0);
  const todayRec = log[todayKey];
  const todayMins = todayRec ? dur(todayRec.b, todayRec.w) : null;

  const debt = useMemo(() => {
    let acc = 0;
    last7.forEach(d => { if (d.mins != null) acc += (goalMin - d.mins); });
    return acc;
  }, [last7, goalMin]);

  const logged = last7.filter(d => d.mins != null);
  const avg = logged.length ? Math.round(logged.reduce((a, d) => a + d.mins, 0) / logged.length) : null;

  const fmtHM = (m) => {
    const sign = m < 0 ? '-' : '';
    const am = Math.abs(m);
    const h = Math.floor(am / 60), mm = am % 60;
    return sign + h + 'h ' + String(mm).padStart(2, '0') + 'm';
  };

  const previewMins = dur(bed, wake);
  const pct = Math.max(0, Math.min(1, (todayMins != null ? todayMins : previewMins) / goalMin));

  const save = () => {
    setLog(p => ({ ...p, [todayKey]: { b: bed, w: wake } }));
  };

  const R = 50, CIRC = 2 * Math.PI * R;
  const fg = 'var(--w-fg)', mut = 'var(--w-mut)', line = 'var(--w-line)';

  const centerMins = todayMins != null ? todayMins : previewMins;
  const centerH = Math.floor(centerMins / 60), centerM = centerMins % 60;

  const maxBar = Math.max(goalMin, ...last7.map(d => d.mins || 0)) || goalMin;

  return (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 16 * s, padding: 18 * s, fontFamily: fontStack }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 18 * s, width: '100%', justifyContent: 'center' }}>
        <div style={{ position: 'relative', width: 116 * s, height: 116 * s, flexShrink: 0 }}>
          <svg width={116 * s} height={116 * s} viewBox="0 0 116 116" style={{ transform: 'rotate(-90deg)' }}>
            <circle cx="58" cy="58" r={R} fill="none" stroke={line} strokeWidth="9" />
            <circle cx="58" cy="58" r={R} fill="none" stroke={accent} strokeWidth="9" strokeLinecap="round" strokeDasharray={CIRC} strokeDashoffset={CIRC * (1 - pct)} style={{ transition: 'stroke-dashoffset 0.7s cubic-bezier(.4,0,.2,1)' }} />
          </svg>
          <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 1 * s }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 1 * s, fontVariantNumeric: 'tabular-nums' }}>
              <span style={{ fontSize: 26 * s, fontWeight: 700, lineHeight: 1, letterSpacing: '-0.02em' }}>{centerH}</span>
              <span style={{ fontSize: 13 * s, fontWeight: 600, color: mut }}>h</span>
              <span style={{ fontSize: 19 * s, fontWeight: 700, lineHeight: 1, marginLeft: 2 * s }}>{String(centerM).padStart(2, '0')}</span>
              <span style={{ fontSize: 12 * s, fontWeight: 600, color: mut }}>m</span>
            </div>
            <div style={{ fontSize: 9.5 * s, letterSpacing: '0.1em', textTransform: 'uppercase', color: mut, fontWeight: 600 }}>{todayMins != null ? Math.round(pct * 100) + '% goal' : 'preview'}</div>
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 9 * s, minWidth: 0 }}>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s }}>
            <span style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: mut, fontWeight: 600 }}>Goal</span>
            <span style={{ fontSize: 15 * s, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{goal}h sleep</span>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s }}>
            <span style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: mut, fontWeight: 600 }}>7-day avg</span>
            <span style={{ fontSize: 15 * s, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{avg != null ? fmtHM(avg) : '—'}</span>
          </div>
          {showDebt ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s }}>
              <span style={{ fontSize: 9.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: mut, fontWeight: 600 }}>Sleep debt</span>
              <span style={{ fontSize: 15 * s, fontWeight: 600, fontVariantNumeric: 'tabular-nums', color: debt > 30 ? accent : fg }}>{logged.length ? (debt > 0 ? fmtHM(debt) : 'none') : '—'}</span>
            </div>
          ) : null}
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 5 * s, width: '100%', height: 44 * s }}>
        {last7.map((d, i) => {
          const h = d.mins != null ? Math.max(0.08, d.mins / maxBar) : 0;
          const hit = d.mins != null && d.mins >= goalMin;
          return (
            <div key={d.k} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 * s, height: '100%', justifyContent: 'flex-end' }}>
              <div style={{ width: '100%', height: 30 * s, display: 'flex', alignItems: 'flex-end', position: 'relative' }}>
                <div style={{ position: 'absolute', left: 0, right: 0, bottom: 30 * s * (goalMin / maxBar), borderTop: `1px dashed ${line}`, opacity: 0.7 }} />
                <div style={{ width: '100%', height: (30 * s * h) + 'px', borderRadius: 3 * s, background: d.mins == null ? line : (hit ? accent : lighten(accent, 0.45)), opacity: d.mins == null ? 0.4 : 1, transition: 'height 0.5s ease' }} />
              </div>
              <span style={{ fontSize: 9 * s, fontWeight: 600, color: d.today ? fg : mut }}>{dayLetters[d.dow]}</span>
            </div>
          );
        })}
      </div>

      {!mini ? (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 * s, width: '100%' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 2 * s, flex: 1 }}>
            <span style={{ fontSize: 8.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: mut, fontWeight: 600, paddingLeft: 2 * s }}>Bed</span>
            <input type="time" value={bed} onChange={e => setBed(e.target.value)} style={{ width: '100%', boxSizing: 'border-box', height: 30 * s, padding: `0 ${7 * s}px`, borderRadius: 7 * s, border: `1px solid ${line}`, background: 'transparent', color: fg, fontSize: 12 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }} />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 2 * s, flex: 1 }}>
            <span style={{ fontSize: 8.5 * s, letterSpacing: '0.08em', textTransform: 'uppercase', color: mut, fontWeight: 600, paddingLeft: 2 * s }}>Wake</span>
            <input type="time" value={wake} onChange={e => setWake(e.target.value)} style={{ width: '100%', boxSizing: 'border-box', height: 30 * s, padding: `0 ${7 * s}px`, borderRadius: 7 * s, border: `1px solid ${line}`, background: 'transparent', color: fg, fontSize: 12 * s, fontWeight: 600, fontFamily: fontStack, fontVariantNumeric: 'tabular-nums' }} />
          </label>
          <button onClick={save} style={{ alignSelf: 'flex-end', height: 30 * s, padding: `0 ${14 * s}px`, borderRadius: 7 * s, border: 'none', background: accent, color: onColor(accent), fontSize: 12 * s, fontWeight: 700, cursor: 'pointer', whiteSpace: 'nowrap' }}>{todayMins != null ? 'Update' : 'Log'}</button>
        </div>
      ) : null}
    </div>
  );
}

