      </div>

      {showCount ? (
        <div style={{ width: '100%', maxWidth: 360 * s, display: 'flex', flexDirection: 'column', gap: 5 * s }}>
          <div style={{ height: 5 * s, borderRadius: 99, background: 'var(--w-line)', overflow: 'hidden' }}>
