            <span>{pct}% of map</span>
            <span>{count} / {total}</span>
          </div>
        </div>
      ) : null}

      {!mini && !showCount ? (
        <div style={{ fontSize: 11 * s, color: 'var(--w-mut)', fontWeight: 500, fontVariantNumeric: 'tabular-nums' }}>{count} / {total}</div>
      ) : null}
    </div>
  );
}

