      {c.showHourly && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 * s }}>
          <svg width="100%" height={44 * s} viewBox={'0 0 ' + W + ' ' + H} preserveAspectRatio="none" style={{ display: 'block', overflow: 'visible' }}>
            <defs>
              <linearGradient id={gid} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={accent} stopOpacity="0.32" />
                <stop offset="100%" stopColor={accent} stopOpacity="0" />
              </linearGradient>
            </defs>
            <path d={areaPath} fill={'url(#' + gid + ')'} />
            <path d={linePath} fill="none" stroke={accent} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
            {pts.map((p, i) => <circle key={i} cx={p[0]} cy={p[1]} r="2.2" fill={accent} vectorEffect="non-scaling-stroke" />)}
          </svg>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            {d.hourly.map(([h, ic, t], i) => (
              <div key={h + i} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1 * s, flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 9.5 * s, color: 'var(--w-mut)', fontWeight: 600 }}>{h}</div>
                <div style={{ fontSize: 11 * s, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>{conv(t)}°</div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: 2 * s, borderTop: '1px solid var(--w-line)', paddingTop: 10 * s }}>
        {days.map(([day, ic, hi, lo, pop]) => (
          <div key={day} style={{ display: 'flex', alignItems: 'center', gap: 10 * s, padding: (4 * s) + 'px 0' }}>
            <div style={{ fontSize: 11.5 * s, fontWeight: 600, width: 34 * s, color: 'var(--w-fg)' }}>{day}</div>
            <WeatherGlyph kind={ic} size={17 * s} color="var(--w-mut)" />
            <div style={{ display: 'flex', alignItems: 'center', gap: 3 * s, width: 38 * s, color: accent, fontSize: 10 * s, fontWeight: 600, opacity: pop >= 30 ? 1 : 0.35 }}>
              <svg width={9 * s} height={9 * s} viewBox="0 0 24 24" fill={accent}><path d="M12 2 C12 2 5 11 5 15 a7 7 0 0 0 14 0 C19 11 12 2 12 2 Z" /></svg>
              <span style={{ fontVariantNumeric: 'tabular-nums' }}>{pop}%</span>
            </div>
            <div style={{ flex: 1, height: 4 * s, borderRadius: 99, background: 'var(--w-line)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'absolute', top: 0, bottom: 0, left: ((lo - d.lo) / Math.max(1, d.hi - d.lo) * 100) + '%', right: (100 - (hi - d.lo) / Math.max(1, d.hi - d.lo) * 100) + '%', borderRadius: 99, background: 'linear-gradient(90deg, ' + lighten(accent, 0.35) + ', ' + accent + ')' }} />
            </div>
            <div style={{ display: 'flex', gap: 6 * s, width: 56 * s, justifyContent: 'flex-end', fontVariantNumeric: 'tabular-nums' }}>
              <span style={{ fontSize: 11.5 * s, fontWeight: 600 }}>{conv(hi)}°</span>
              <span style={{ fontSize: 11.5 * s, fontWeight: 500, color: 'var(--w-mut)' }}>{conv(lo)}°</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
